package app.rwun;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.widget.*;import android.view.*;import java.util.concurrent.*;import org.json.*;import java.time.*;
/** Foreground-only local coaching. No network call is made by Generate. */
public final class OfflineCoachActivity extends Activity {
 private final UiKit.Palette p=new UiKit.Palette(true);private final ExecutorService io=Executors.newSingleThreadExecutor();private final Handler handler=new Handler(Looper.getMainLooper());private LinearLayout body;private TextView state,output;private ProgressBar progress;private RunStore store;private boolean bound,busy;private Future<?> transferTask;private String providedFingerprint;private int operation,requestSerial;private Messenger service;private String summary,fingerprint,result="";private long started;
 private final Messenger replies=new Messenger(new Handler(Looper.getMainLooper(),m->{if((m.what==GemmaService.RESULT||m.what==GemmaService.FAILURE)&&bound&&m.getData().getInt("ticket")==requestSerial){boolean stale=operation==GemmaService.GENERATE&&!fingerprint.equals(store.proposalFingerprint());result=stale?"Running history changed. Generate a fresh insight.":m.getData().getString("text","");boolean success=m.what==GemmaService.RESULT;release();show();state.setText((success&&!stale?"Completed locally in "+((SystemClock.elapsedRealtime()-started)/1000)+"s":"Offline coach unavailable")+" · your plan is unchanged.");output.setText(result);}return true;}));
 private final ServiceConnection connection=new ServiceConnection(){public void onServiceConnected(ComponentName name,IBinder binder){service=new Messenger(binder);android.os.Message request=android.os.Message.obtain(null,operation);request.replyTo=replies;Bundle b=new Bundle();b.putString("summary",summary);b.putInt("ticket",requestSerial);request.setData(b);try{service.send(request);}catch(RemoteException e){fail("The local model process could not start.");}}public void onServiceDisconnected(ComponentName name){fail("The local model process stopped. Your plan is unchanged. Try again with more free memory.");}};
 public void onCreate(Bundle state){super.onCreate(state);store=new RunStore(this);providedFingerprint=getIntent().getStringExtra("fingerprint");summary=getIntent().getStringExtra("summary");if(summary==null)summary=summary(store);if(state!=null)result=state.getString("result","");show();}
 protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("result",result);}
 protected void onStop(){if(bound){release();result="Generation cancelled when this screen closed. Tap Generate to try again.";}super.onStop();}
 protected void onDestroy(){requestSerial++;release();if(transferTask!=null)transferTask.cancel(true);io.shutdownNow();super.onDestroy();}
 static String summary(RunStore store){var evidence=store.runs().stream().map(r->new RaceTraining.Evidence(LocalDate.parse(r.date()),r.km(),r.seconds(),r.rpe(),r.fatigue(),r.pain(),r.rpe()>0&&!r.source().startsWith("Health Connect")&&!r.source().equals("Strava"))).collect(java.util.stream.Collectors.toList());var r=RaceTraining.review(evidence,LocalDate.now(),store.resting());return "Runs in 28 days: "+r.runs28()+"; distance: "+r.km28()+" km; days since last recorded run: "+r.daysSinceLast()+" (-1 means unknown); proposed factor: "+r.factor()+"; training hold: "+r.hold()+". Rule explanation: "+r.reason();}
 private int dp(int x){return UiKit.dp(this,x);}private void text(String s,int n,boolean bold){body.addView(UiKit.label(this,s,n,bold?p.ink:p.muted,bold));}
 private void action(String s,Runnable run){Button b=UiKit.action(this,p,s,()->{try{run.run();}catch(Exception e){fail(UserErrors.message(e));}});b.setEnabled(!busy);body.addView(b);}
 private void show(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(p.background);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i.consumeSystemWindowInsets();});LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.addView(UiKit.iconButton(this,p,R.drawable.ic_arrow_back,"Back",this::finish),new LinearLayout.LayoutParams(dp(56),dp(56)));top.addView(UiKit.label(this,"Offline Coach",19,p.ink,true));root.addView(top);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(20),dp(20),dp(20),dp(28));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
  text("Your coach. On your phone.",28,true);text("Gemma explains your training summary offline. It cannot change your plan or clear a hold.",16,false);text(GemmaModel.NAME+" · INT4",21,true);text(OfflineModels.ready(this)?"Verified model installed · 557 MiB":"Model not installed · 557 MiB separate download",14,false);
  state=UiKit.label(this,busy?"Working… keep this screen open.":"Ready when you are.",14,p.primary,false);body.addView(state);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);progress.setVisibility(busy?View.VISIBLE:View.GONE);body.addView(progress,new LinearLayout.LayoutParams(-1,dp(5)));
  if(OfflineModels.ready(this)){action("Generate offline insight",()->start(GemmaService.GENERATE));action("Remove local model",()->new AlertDialog.Builder(this).setTitle("Remove the model?").setMessage("This frees the model's storage. Your training history and plans stay on this phone.").setNegativeButton("Keep",null).setPositiveButton("Remove",(d,w)->{try{OfflineModels.remove(this);result="";show();}catch(Exception e){fail(UserErrors.message(e));}}).show());}
  else{action("Get Gemma model",()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(GemmaModel.SOURCE))));action("Import downloaded model",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,311);});action("Try direct download",()->new AlertDialog.Builder(this).setTitle("Download 557 MiB?").setMessage("This contacts the model publisher over the internet. Gemma licence acceptance may be required on their website. If refused, download the listed file there and import it. Use Wi-Fi and keep this screen open.").setNegativeButton("Cancel",null).setPositiveButton("Download",(d,w)->transfer(null)).show());text("File: "+GemmaModel.FILE,12,false);}
  action("Check local runtime",()->start(GemmaService.RUNTIME));if(busy){Button cancel=UiKit.action(this,p,"Cancel",()->{if(bound){release();result="Cancelled. Your plan is unchanged.";show();}else if(transferTask!=null){requestSerial++;transferTask.cancel(true);busy=false;result="Import cancelled. Installed model status is shown above.";show();}});body.addView(cancel);}
  text("SUMMARY USED",12,true);text(summary,14,false);output=UiKit.label(this,result,16,p.ink,false);body.addView(output);text("Generation stays on this phone. No API key or account is required. Model quality and S23 performance still need physical testing; verify generated explanations against the plan.",12,false);
 }
 private void start(int action){if(busy)return;if(action==GemmaService.GENERATE){if(providedFingerprint!=null&&!providedFingerprint.equals(store.proposalFingerprint()))throw new IllegalStateException("Your history or preview changed. Return to the plan and open a fresh insight.");if(providedFingerprint==null)summary=summary(store);}if(action==GemmaService.GENERATE&&(!store.checkpoint().isEmpty()||store.indoorPending()))throw new IllegalStateException("Finish or recover your active session before using the offline coach.");requestSerial++;busy=true;operation=action;fingerprint=store.proposalFingerprint();started=SystemClock.elapsedRealtime();show();bound=bindService(new Intent(this,GemmaService.class),connection,BIND_AUTO_CREATE);if(!bound){busy=false;fail("Could not start the local coach process.");return;}handler.postDelayed(()->{if(bound)fail("The local coach timed out and was stopped. Your plan is unchanged.");},180000);}
 private void release(){handler.removeCallbacksAndMessages(null);if(bound){bound=false;try{unbindService(connection);}catch(Exception ignored){}}service=null;busy=false;}
 private void fail(String message){release();result=message;if(!isDestroyed()){show();state.setText(message);}}
 protected void onActivityResult(int request,int response,Intent data){super.onActivityResult(request,response,data);if(request==311&&response==RESULT_OK&&data!=null&&data.getData()!=null)transfer(data.getData());}
 private void transfer(Uri source){if(busy)return;int ticket=++requestSerial;busy=true;show();transferTask=io.submit(()->{try{GemmaModel.Progress callback=count->handler.post(()->{if(ticket==requestSerial&&!isDestroyed()){progress.setProgress((int)(count*100/GemmaModel.BYTES));state.setText("Verifying model · "+count/1024/1024+" / 557 MiB");}});final long[] last={0};GemmaModel.Progress throttled=count->{long now=SystemClock.elapsedRealtime();if(now-last[0]>500){last[0]=now;callback.bytes(count);}};if(source==null)OfflineModels.download(this,throttled);else{java.io.InputStream input=getContentResolver().openInputStream(source);if(input==null)throw new java.io.IOException("Could not open that model file");OfflineModels.install(this,input,throttled);}handler.post(()->{if(ticket!=requestSerial)return;busy=false;if(!isDestroyed()){result="Model checksum verified and installed. Generate an insight to test it on this phone.";show();}});}catch(Exception e){handler.post(()->{if(ticket==requestSerial&&!isDestroyed())fail(UserErrors.message(e));});}});}
}
